  function hyphenateWord(word,max){if(word.length<=max)return[word];const parts=[],vowels='aeiouyäöüAEIOUYÄÖÜ';let rest=word;while(rest.length>max){let cut=-1;for(let i=Math.min(max-1,rest.length-1);i>=4;i--){if(vowels.includes(rest[i-1])&&!vowels.includes(rest[i])){cut=i;break}}if(cut<4)cut=Math.max(3,max-1);parts.push(rest.slice(0,cut)+'-');rest=rest.slice(cut)}parts.push(rest);return parts}
  function wrapLabel(text,width){const max=Math.max(8,Math.floor(width/8)),lines=[];for(const paragraph of String(text||'').split('\n')){let line='';for(const word of paragraph.split(/\s+/)){const pieces=hyphenateWord(word,max);if(pieces.length===1){if(line&&line.length+word.length+1>max){lines.push(line);line=''}line+=(line?' ':'')+word;continue}if(line){if(line.length+1+pieces[0].length<=max){line+=(line?' ':'')+pieces.shift()}else{lines.push(line);line=''}}pieces.forEach((piece,i)=>{if(i<pieces.length-1){lines.push(piece)}else{line=piece}})}lines.push(line)}return lines}
