  function validateModel(data){
    if(data?.version!==1||!Array.isArray(data.elements)||!Array.isArray(data.relations))throw Error('Keine gültige Modelldatei.');
    const copy=JSON.parse(JSON.stringify(data));copy.groups=copy.groups||[];copy.view=copy.view||{};copy.title=String(copy.title||'Mein Staatsmodell');
    if(copy.elements.length>200||copy.relations.length>500)throw Error('Das Modell ist zu groß (maximal 200 Elemente / 500 Beziehungen).');
    const ids=new Set();for(const n of [...copy.elements,...copy.groups,...copy.relations]){if(typeof n.id!=='string'||!/^[-\w]+$/.test(n.id)||ids.has(n.id))throw Error('Ungültige oder doppelte Kennung.');ids.add(n.id)}
    const ni=new Set(copy.elements.map(n=>n.id)),gi=new Set(copy.groups.map(g=>g.id));
    for(const n of copy.elements){if(!TYPES.some(t=>t[0]===n.type))throw Error('Unbekannter Elementtyp.');n.label=String(n.label||'');n.properties=n.properties||{};if(n.type==='collection')n.properties.items=collectionItems(n);n.visual=n.visual||{};if(!Number.isFinite(n.visual.x)||!Number.isFinite(n.visual.y))throw Error('Ungültige Elementposition.');if(n.parentId&&!ni.has(n.parentId))throw Error('Übergeordnetes Element fehlt.');if(n.groupId&&!gi.has(n.groupId))n.groupId=''}
    for(const g of copy.groups){if(!['x','y','w','h'].every(k=>Number.isFinite(g[k]))||g.w<1||g.h<1)throw Error('Ungültige Bereichsgröße.');if(g.parentGroupId&&!gi.has(g.parentGroupId))throw Error('Übergeordneter Bereich fehlt.')}
    for(const [items,key] of [[copy.elements,'parentId'],[copy.groups,'parentGroupId']])for(const item of items){const seen=new Set([item.id]);let p=item[key];while(p){if(seen.has(p))throw Error('Kreisförmige Verschachtelung.');seen.add(p);p=items.find(n=>n.id===p)?.[key]}}
    for(const r of copy.relations){
      r.type=String(r.type||'').trim();const standard=Object.values(RELATIONS).flat().includes(r.type),custom=RELATIONS[r.category]&&r.type.length>0&&r.type.length<=100;
      if(!ni.has(r.source)||!ni.has(r.target)||r.source===r.target||(!standard&&!custom))throw Error('Ungültige Beziehung.');
      r.visual=r.visual||{};if(r.visual.manualRoute&&(!Array.isArray(r.visual.manualRoute)||r.visual.manualRoute.length<2||r.visual.manualRoute.length>200||r.visual.manualRoute.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y))))throw Error('Ungültiger manueller Pfeilverlauf.');r.properties=r.properties||{};
      for(const end of ['sourcePort','targetPort']){const p=r.visual[end];if(p&&(!['left','right','top','bottom'].includes(p.side)||!Number.isFinite(p.t)||p.t<0||p.t>1))throw Error('Ungültiger Pfeilanschluss.')}
    }
    return copy
  }
